package com.itmeansbigmountain.rivalradar;

import net.runelite.api.Client;
import net.runelite.api.graphics.Raster;
import net.runelite.awt.render.BackgroundOp;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import java.awt.*;

import lombok.extern.slf4j.Slf4j;

public class RivalRadarOverlay extends Overlay {

    private final RivalRadarPlugin plugin;
    private final RivalRadarConfig config;

    public RivalRadarOverlay(RivalRadarPlugin plugin, RivalRadarConfig config) {
        this.plugin = plugin;
        this.config = config;

        // Configure overlay properties
        setPosition(Overlays.BOTTOM_LEFT.getAdditions());
        setLayer(OverlayLayer.ABOVE_INTERFACE);
    }

    @Override
    public Dimension render(Client client) {
        if (!isEnabled()) {
            return null;
        }

        try {
            // Get local player name and XP
            String localName = plugin.getLocalPlayerName();
            double localXP = plugin.getLocalPlayerXP();

            // Prepare overlay text
            StringBuilder text = new StringBuilder("Local XP: " + (int)localXP + "\n");

            // Add rival comparisons
            for (Map.Entry<String, Double> entry : plugin.getRivalXPCache().entrySet()) {
                String rivalName = entry.getKey();
                double rivalXP = entry.getValue();
                if (rivalXP > 0) {
                    text.append("• ").append(rivalName).append(": ").append((int)rivalXP).append("\n");
                }
            }

            return renderText(text.toString());
        } catch (Exception e) {
            log.warn("Error rendering RivalRadarOverlay", e);
            return null;
        }
    }

    private Dimension renderText(String text) {
        // Simple text rendering - can be enhanced later
        try {
            FontMetrics fm = Minecraft.getFontMetrics();
            int width = fm.getLabel().computeWidth(text);
            int height = fm.getLabel().computeHeight(text) + 1;
            width = Math.max(width, 1);
            height = Math.max(height, 1);

            return new Dimension(width + 2, height + 2);
        } catch (Exception e) {
            return new Dimension(200, 100);
        }
    }
}
</parameter>
